const driveFolderTrashMark = `-- name: DriveFolderTrashMark :execrows
WITH RECURSIVE tree(id) AS (
 SELECT f.id FROM drive_folders f WHERE f.tenant_id=$3 AND f.space_id=$4
  AND f.id=$2 AND f.deleted_at IS NULL
 UNION
 SELECT c.id FROM drive_folders c JOIN tree p ON p.id=c.parent_id
 WHERE c.tenant_id=$3 AND c.space_id=$4 AND c.deleted_at IS NULL
)
UPDATE drive_folders f SET deleted_at=now(),trash_batch_id=$1,trash_root=(f.id=$2),updated_at=now()
WHERE f.tenant_id=$3 AND f.space_id=$4 AND f.id IN (SELECT id FROM tree)
`

