const driveUploadStatus = `-- name: DriveUploadStatus :one
SELECT u.id,u.space_id,COALESCE(u.folder_id,0)::bigint AS folder_id,u.name,u.size,u.state,u.expires_at,
 COALESCE((SELECT d.id FROM drive_files d WHERE d.tenant_id=u.tenant_id AND d.file_id=u.file_id),0)::bigint AS completed_file_id
FROM drive_uploads u JOIN drive_spaces s ON s.tenant_id=u.tenant_id AND s.id=u.space_id
WHERE u.tenant_id=$1 AND u.id=$2 AND u.owner_id=$3
 AND ((s.kind='personal' AND s.owner_id=$3) OR
  (s.kind='shared' AND EXISTS (SELECT 1 FROM drive_members m WHERE m.tenant_id=s.tenant_id AND m.space_id=s.id
   AND m.role IN ('admin','editor') AND (m.account_id=$3 OR m.department_id=$4))))
`

type DriveUploadStatusParams struct {
	TenantID     string
	UploadID     int64
	ActorID      int64
	DepartmentID pgtype.Int8
}

type DriveUploadStatusRow struct {
	ID              int64
	SpaceID         int64
	FolderID        int64
	Name            string
	Size            int64
	State           string
	ExpiresAt       pgtype.Timestamptz
	CompletedFileID int64
}

func (q *Queries) DriveUploadStatus(ctx context.Context, arg DriveUploadStatusParams) (DriveUploadStatusRow, error) {
	row := q.db.QueryRow(ctx, driveUploadStatus,
		arg.TenantID,
		arg.UploadID,
		arg.ActorID,
		arg.DepartmentID,
	)
	var i DriveUploadStatusRow
	err := row.Scan(
		&i.ID,
		&i.SpaceID,
		&i.FolderID,
		&i.Name,
		&i.Size,
		&i.State,
		&i.ExpiresAt,
		&i.CompletedFileID,
	)
	return i, err
}
